Using RING_API_RETMANAGEDCPOINTER() the Ring extensions written in C/C++ languages can return a managed pointer to Ring. This pointer can be controlled by the Ring VM using reference counting. This is important to avoid the need to write code that free the unmanaged resources like QPixMap objects in RingQt. Also the Code Generator for extensions is updated to automatically use RING_API_RETMANAGEDCPOINTER() based on need. The next example from ring_qt.cpp - QPixMap Class - Scaled() Method. 	RING_FUNC(ring_QPixmap_scaled) 	{ 		QPixmap *pObject ; 		if ( RING_API_PARACOUNT != 5 ) { 			RING_API_ERROR(RING_API_BADPARACOUNT); 			return ; 		} 		RING_API_IGNORECPOINTERTYPE ; 		if ( ! RING_API_ISCPOINTER(1) ) { 			RING_API_ERROR(RING_API_BADPARATYPE); 			return ; 		} 		pObject = (QPixmap *) RING_API_GETCPOINTER(1,"QPixmap"); 		if ( ! RING_API_ISNUMBER(2) ) { 			RING_API_ERROR(RING_API_BADPARATYPE); 			return ; 		} 		if ( ! RING_API_ISNUMBER(3) ) { 			RING_API_ERROR(RING_API_BADPARATYPE); 			return ; 		} 		if ( ! RING_API_ISNUMBER(4) ) { 			RING_API_ERROR(RING_API_BADPARATYPE); 			return ; 		} 		if ( ! RING_API_ISNUMBER(5) ) { 			RING_API_ERROR(RING_API_BADPARATYPE); 			return ; 		} 		{ 			QPixmap *pValue ; 			pValue = new QPixmap() ; 			*pValue = pObject->scaled( (int ) RING_API_GETNUMBER(2), 				 (int ) RING_API_GETNUMBER(3), 				 (Qt::AspectRatioMode )  (int) RING_API_GETNUMBER(4), 				 (Qt::TransformationMode )  (int) RING_API_GETNUMBER(5)); 			RING_API_RETMANAGEDCPOINTER(pValue,"QPixmap",ring_QPixmap_freefunc); 		} 	} The function that will free the memory takes two parameters (Ring State and the allocated Memory Pointer) 

### Syntax:
```ring
	RING_API_RETMANAGEDCPOINTER(void *pValue,const char *cPointerType,
					void (* pFreeFunc)(void *,void *))

```

### Code Example:
```ring
void ring_QPixmap_freefunc(void *pState,void *pPointer)
{
	QPixmap *pObject ; 
	pObject = (QPixmap *) pPointer;
	delete pObject ;
}



```

باستخدام RING_API_RETMANAGEDCPOINTER()، يمكن لامتدادات رينج المكتوبة بلغات C/C++ إرجاع مؤشر مُدار إلى رينج. يمكن التحكم في هذا المؤشر بواسطة رينج VM باستخدام العد المرجعي. يعد هذا أمرًا مهمًا لتجنب الحاجة إلى كتابة تعليمات برمجية تحرر الموارد غير المُدارة مثل كائنات QPixMap في RingQt. يتم أيضًا تحديث Code Generator للملحقات لاستخدام RING_API_RETMANAGEDCPOINTER() تلقائيًا بناءً على الحاجة. المثال التالي من Ring_qt.cpp - فئة QPixMap - طريقة Scaled(). 	RING_FUNC(ring_QPixmap_scaled) { QPixmap *pObject ; 		إذا ( RING_API_PARACOUNT != 5 ) { RING_API_ERROR(RING_API_BADPARACOUNT); 			يعود ؛ 		} RING_API_IGNORECPOINTERTYPE ; 		إذا ( ! RING_API_ISCPOINTER(1) ) { RING_API_ERROR(RING_API_BADPARATYPE); 			يعود ؛ 		} pObject = (QPixmap *) RING_API_GETCPOINTER(1,"QPixmap"); 		إذا ( ! RING_API_ISNUMBER(2) ) { RING_API_ERROR(RING_API_BADPARATYPE); 			يعود ؛ 		} إذا ( ! RING_API_ISNUMBER(3) ) { RING_API_ERROR(RING_API_BADPARATYPE); 			يعود ؛ 		} إذا ( ! RING_API_ISNUMBER(4) ) { RING_API_ERROR(RING_API_BADPARATYPE); 			يعود ؛ 		} إذا ( ! RING_API_ISNUMBER(5) ) { RING_API_ERROR(RING_API_BADPARATYPE); 			يعود ؛ 		} { QPixmap *pValue ; 			pValue = QPixmap() الجديد; 			*pValue = pObject->scaled( (int ) RING_API_GETNUMBER(2), (int ) RING_API_GETNUMBER(3), (Qt::AspectRatioMode) (int) RING_API_GETNUMBER(4), (Qt::TransformationMode ) (int) RING_API_GETNUMBER(5)); 			RING_API_RETMANAGEDCPOINTER(pValue,"QPixmap",ring_QPixmap_freefunc); 		} } الدالة التي ستحرر الذاكرة تأخذ معلمتين (حالة الحلقة ومؤشر الذاكرة المخصص)

### الصيغة البرمجية:
```ring
	RING_API_RETMANAGEDCPOINTER(void *pValue,const char *cPointerType,
					void (* pFreeFunc)(void *,void *))

```

