						gl_map_rgb(t*random(255),
						t*2,t*3),1)
						gl_draw_rectangle(x+t*2,y+t*2,
						x-t*2,y-t*2,
						gl_map_rgb(t*random(255),
						t*2,t*3),1)
					next
				}
			}
			keypress = func oGame,oSelf,nKey {
				oSelf { 
					Switch nKey	
					on KEY_LEFT	
						x -= 10			
					on KEY_RIGHT
						x += 10
					on KEY_UP
						y -= 10
					on KEY_DOWN
						y += 10
					off
				}
			}
		}

