new qApp { 
	openWindow(:CustomersReportController)
	exec()
}

class CustomersReportView 

win = new window() { 
	setwindowtitle("Report Window")
	setgeometry(100, 100, 500, 500)
	web = new webview(win) { 
		setgeometry(100, 100, 1000, 500)
		loadpage( new QURL("file:///"+substr(currentdir(), "\", "/")+"/report.html"))
	}
	new pushbutton(win) { 
		setGeometry(100, 20, 100, 30)
		settext("Print")
		setclickevent(Method(:PrintEvent))
	}
	showMaximized()
}

class CustomersReportController from WindowsControllerParent 

	oPrinter

	oView = new CustomersReportView 

	func Start 

		CreateReport()


	func CreateReport 

		mypage = new HtmlPage { 
			h1 { text("Customers Report")}
			Table 
			{ 
				style = stylewidth("100%")+stylegradient(4)
				TR 
				{ 
					TD { WIDTH = "10%" text("Customers Count : ")}
					TD { text(100)}
				}
			}
			Table 
			{ 
				style = stylewidth("100%")+stylegradient(26)
				TR 
				{ 
					style = stylewidth("100%")+stylegradient(24)
					TD { text("Name ")}
					TD { text("Age")}
					TD { text("Country")}
					TD { text("Job")}
					TD { text("Company")}
				}
				for x = 1 to 100
					TR 
					{ 
						TD { text("Test")}
						TD { text("30")}
						TD { text("Egypt")}
						TD { text("Sales")}
						TD { text("Future")}
					}
				next 
			}
		}
		write("report.html", mypage.output())


	func PrintEvent 

		oPrinter = new QPrinter(0) { 
			setoutputformat(1)
			setoutputfilename("report.pdf")
		}
		oView.web.print(oPrinter, Method(:OpenPDF))

	func OpenPDF 

		oPrinter.Delete()
		new QDesktopServices { 
			OpenURL( new qURL("report.pdf"))
		}


